import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        String[] words = new String[(int) n];
        for (int i = 0; i < words.length; i++) words[i] = next();

        int total = 1;
        for (String w : words) total += w.length();
        int[][] child = new int[total][26];
        for (int[] row : child) Arrays.fill(row, -1);
        int[] cnt = new int[total];
        int size = 1;
        for (String w : words) {
            int node = 0;
            for (char c : w.toCharArray()) {
                int k = c - 'a';
                if (child[node][k] < 0) child[node][k] = size++;
                node = child[node][k];
                cnt[node]++;
            }
        }
        StringBuilder out = new StringBuilder();
        for (String w : words) {
            int node = 0;
            for (int i = 0; i < w.length(); i++) {
                node = child[node][w.charAt(i) - 'a'];
                if (cnt[node] == 1) {
                    out.append(w, 0, i + 1).append("\n");
                    break;
                }
            }
        }
        System.out.print(out);
    }
}
